#!/usr/bin/env bash
set -euo pipefail
WORKSPACE="/home/kavia/workspace/code-generation/recipe-finding-app-98606-98494/Database"
cd "$WORKSPACE"
[ -f package.json ] || { echo 'package.json missing, run scaffold' >&2; exit 6; }
TS=$(date +%s)
cp package.json "package.json.bak.$TS"
PRE_SUM=$(sha256sum package.json | cut -d' ' -f1)
node - <<'NODE'
const fs=require('fs');const p=require('./package.json');let changed=false;
p.scripts=p.scripts||{};
if(!p.scripts.test){p.scripts.test='react-scripts test --watchAll=false --runInBand';changed=true}
if(!p.scripts.build){p.scripts.build='react-scripts build';changed=true}
if(!p.scripts.start){p.scripts.start='react-scripts start';changed=true}
// ensure devDependencies for testing
p.devDependencies=p.devDependencies||{};
if(!p.devDependencies['@testing-library/react']){p.devDependencies['@testing-library/react']='^14.0.0';changed=true}
if(!p.devDependencies['@testing-library/jest-dom']){p.devDependencies['@testing-library/jest-dom']='^6.0.0';changed=true}
if(changed) fs.writeFileSync('package.json',JSON.stringify(p,null,2));
NODE
POST_SUM=$(sha256sum package.json | cut -d' ' -f1)
MUTATED=0
if [ "$PRE_SUM" != "$POST_SUM" ]; then MUTATED=1; fi
if [ "$MUTATED" -eq 1 ]; then
  npm install --silent --no-audit --no-fund || { echo 'npm install failed' >&2; cp "package.json.bak.$TS" package.json; exit 7; }
else
  if [ -f package-lock.json ]; then
    npm ci --silent --no-audit --no-fund || { echo 'npm ci failed' >&2; exit 8; }
  else
    npm install --silent --no-audit --no-fund || { echo 'npm install failed' >&2; exit 9; }
  fi
fi
# Print installed versions if present
[ -f node_modules/react/package.json ] && node -p "require('./node_modules/react/package.json').version" || echo 'react not installed' >&2
[ -f node_modules/react-dom/package.json ] && node -p "require('./node_modules/react-dom/package.json').version" || echo 'react-dom not installed' >&2
if [ -f node_modules/react-scripts/package.json ]; then node -p "require('./node_modules/react-scripts/package.json').version"; else echo 'react-scripts missing' >&2; fi
# Optional server stub creation (isolated)
if [ "${CREATE_STUB:-0}" = "1" ]; then
  mkdir -p server && cd server
  if [ ! -f package.json ]; then
    cat > package.json <<'PKG'
{ "name":"server-stub","version":"0.0.0","private":true,"scripts":{"start":"node server_stub.js"},"dependencies":{"express":"^4.18.2"} }
PKG
  fi
  cat > server_stub.js <<'JS'
const express=require('express');const app=express();app.use(express.json());app.get('/api/recipes',(r,s)=>s.json({recipes:[]}));app.post('/api/ai',(r,s)=>s.json({reply:'stub'}));const p=process.env.PORT||3001;app.listen(p,()=>console.log('stub listening',p));
JS
  npm install --silent --no-audit --no-fund || { echo 'server npm install failed' >&2; exit 10; }
  cd "$WORKSPACE"
fi
exit 0

#!/usr/bin/env bash
set -euo pipefail
WORKSPACE="/home/kavia/workspace/code-generation/recipe-finding-app-98606-98494/Database"
cd "$WORKSPACE"
mkdir -p src/__tests__
if [ ! -f src/setupTests.js ]; then
  cat > src/setupTests.js <<'JS'
import '@testing-library/jest-dom';
JS
fi
if [ -z "$(ls -A src/__tests__ 2>/dev/null || true)" ]; then
  cat > src/__tests__/App.test.js <<'JS'
import React from 'react';
import {render, screen} from '@testing-library/react';
import App from '../App';
test('renders heading', ()=>{ render(<App/>); expect(screen.getByText(/Recipe Finder/i)).toBeInTheDocument(); });
JS
fi
npm test --silent -- --watchAll=false || { echo 'Tests failed' >&2; exit 11; }
exit 0
